function gatewayProfileKey(row) {
    const candidates = [row.alias, row.name, row.id];
    for (const candidate of candidates) {
        if (!candidate)
            continue;
        const normalised = String(candidate).trim().toLowerCase().replace(/\s+/g, "");
        if (exports.GATEWAY_PROFILES[normalised])
            return normalised;
    }
    return null;
}
function getGatewayProfile(row) {
    const key = gatewayProfileKey(row);
    return key ? exports.GATEWAY_PROFILES[key] : null;
}
